  const icon = name => `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${PATHS[name] || PATHS.table}"/></svg>`;
  $$('[data-icon]').forEach(n => n.innerHTML = icon(n.dataset.icon));
