    if(col.format==='bar'&&numeric(field(col.id))){const values=resultRows().map(r=>r[col.id]).filter(v=>v!==null&&Number.isFinite(Number(v))).map(Number);const max=Math.max(1,...values);bar=Math.max(0,Math.min(100,100*Number(row[col.id]||0)/max));}
