    const data=resultRows(),cols=visibleColumns(); const pinnedLeft={};let left=42;
    cols.forEach(c=>{c.width=Math.max(88,Math.min(480,Number(c.width)||140));if(c.pinned){pinnedLeft[c.id]=left;left+=c.width;}});
    $('#chips').innerHTML=(view.filters.length||view.groups.length)?`${view.groups.length?`<span class="filter-chip">${icon('group')}${view.groups.map(id=>esc(field(id)?.label||id)).join(' <span>›</span> ')}<button data-action="clear-groups" aria-label="Убрать группировку">×</button></span>`:''}${view.filters.map((f,i)=>`<span class="filter-chip">${esc(field(f.field)?.label||f.field)} ${esc(opLabel(f.op))} ${esc(f.value??'')}<button data-remove-filter="${i}" aria-label="Удалить фильтр ${i+1}">×</button></span>`).join('')}`:'';
    $('#chips').hidden=!$('#chips').innerHTML;
