    let html=`<table class="data-table" aria-label="Товары, текущее представление" style="width:${42+cols.reduce((s,c)=>s+c.width,0)}px"><colgroup><col style="width:42px">${cols.map(c=>`<col style="width:${c.width}px">`).join('')}</colgroup><thead><tr><th class="row-utility pinned" style="left:0"><input type="checkbox" id="select-all" aria-label="Выбрать все отфильтрованные строки" ${data.length&&data.every(r=>selected.has(r.id))?'checked':''}></th>${cols.map(c=>{const f=field(c.id),sortIndex=view.sorts.findIndex(s=>s.field===c.id);return `<th class="${c.pinned?'pinned':''}" style="${c.pinned?'left:'+pinnedLeft[c.id]+'px;':''}${color(c.color)?'--cell-tint:'+color(c.color)+';':''}"><button class="col-heading" data-column="${esc(c.id)}" aria-label="Настроить колонку ${esc(f.label)}"><span class="col-type" aria-hidden="true">${numeric(f)?'#':f.type==='enum'?'◉':'Aa'}</span><span class="col-label">${esc(f.label)}</span>${sortIndex>=0?`<span class="sort-mark">${view.sorts[sortIndex].direction==='desc'?'↓':'↑'}${view.sorts.length>1?sortIndex+1:''}</span>`:icon('down')}</button><span class="resize-handle" role="separator" aria-orientation="vertical" aria-label="Ширина колонки ${esc(f.label)}" tabindex="0" data-resize="${esc(c.id)}"></span></th>`;}).join('')}</tr></thead><tbody>`;
    let rowNumber=0;
