    if(view.groups.length){const draw=(nodes,depth)=>nodes.map(n=>{const closed=view.collapsed.includes(n.key);const summary=`${aggregateText(n.rows,'sales')} продаж · ${aggregateText(n.rows,'revenue')}`;return `<tr class="group-row depth-${depth}"><td colspan="${cols.length+1}"><button class="group-toggle" style="padding-left:${14+depth*22}px" data-group-key="${esc(n.key)}" aria-expanded="${!closed}">${icon(closed?'chevron':'down')}<span class="group-path">${esc(field(n.field)?.label||n.field)}</span><strong>${esc(n.value===null||n.value===undefined||n.value===''?'Не задано':n.value)}</strong><span class="group-count">${n.rows.length}</span><span class="group-summary">${summary}</span></button></td></tr>${closed?'':n.children?.length?draw(n.children,depth+1):n.rows.map(rowHTML).join('')}`;}).join('');html+=draw(E.groupRows(data,view.groups,allFields()),0);}else html+=data.map(rowHTML).join('');
    if(!data.length)html+=`<tr><td colspan="${cols.length+1}"><div class="view-empty"><h3>По этим условиям ничего не найдено</h3><p>Измените поиск или фильтр. Исходные данные сохранены.</p><button class="btn" data-action="clear-filters">Сбросить поиск и фильтры</button></div></td></tr>`;
